import sys


def part_brute(s):
    n = len(s)
    res = []

    def is_pal(x):
        return x == x[::-1]

    def dfs(i, path):
        if i == n:
            res.append(path[:])
            return
        for j in range(i, n):
            path.append(s[i:j + 1])
            dfs(j + 1, path)
            path.pop()

    dfs(0, [])
    return [p for p in res if all(is_pal(x) for x in p)]


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s = data[0]
    for part in part_brute(s):
        print(' '.join(part))

import sys


def part_opt(s):
    n = len(s)
    res = []

    def is_pal(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True

    def dfs(i, path):
        if i == n:
            res.append(path[:])
            return
        for j in range(i, n):
            if is_pal(i, j):
                path.append(s[i:j + 1])
                dfs(j + 1, path)
                path.pop()

    dfs(0, [])
    return res


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s = data[0]
    for part in part_opt(s):
        print(' '.join(part))

import sys


def part_best(s):
    n = len(s)
    if n == 0:
        return []
    dp = [[False] * n for _ in range(n)]
    for j in range(n):
        for i in range(j + 1):
            if s[i] == s[j] and (j - i <= 2 or dp[i + 1][j - 1]):
                dp[i][j] = True
    res = []

    def dfs(i, path):
        if i == n:
            res.append(path[:])
            return
        for j in range(i, n):
            if dp[i][j]:
                path.append(s[i:j + 1])
                dfs(j + 1, path)
                path.pop()

    dfs(0, [])
    return res


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s = data[0]
    for part in part_best(s):
        print(' '.join(part))
